import { blockId } from './flow-id.js';

const PAGE_BREAK_COMMENT_RE = /\s*(page-break-before|break-before)\s*/i;

// Node type constants (avoids relying on the global Node in non-DOM contexts).
const ELEMENT_NODE = 1;
const TEXT_NODE = 3;
const COMMENT_NODE = 8;

function escapeHtml(text) {
  return String(text ?? '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;');
}

// Inline SVG and MathML go with the other active content: their element and attribute surface
// (scripts, `use`, animations, foreignObject) needs an allow-list of its own, which this sanitizer
// does not carry. Documents embed vector art through `<img src>`.
const UNSAFE_ELEMENTS = 'script,style,iframe,object,embed,base,meta,link,template,svg,math';
const URL_ATTRIBUTES = new Set(['href', 'src', 'xlink:href', 'action', 'data', 'poster', 'background', 'cite']);
const ALLOWED_SCHEMES = new Set(['http', 'https', 'mailto', 'tel']);
// Media sources may also embed a raster image or name a same-document blob, both of which a CMS or
// the template itself produces. Never a document (`data:text/html`) and never SVG
// (`data:image/svg+xml` can carry scripts in some embeddings).
const MEDIA_ATTRIBUTES = new Set(['src', 'poster', 'srcset']);
const EMBEDDED_RASTER_IMAGE_RE = /^data:image\/(?:png|jpe?g|gif|webp|avif|bmp)[;,]/i;

function isAllowedUrl(value, attributeName) {
  // URL parsers ignore ASCII controls inside schemes. Entities have already
  // been decoded by the HTML parser, including numeric and mixed-case forms.
  const normalized = [...String(value ?? '').trim()].filter((char) => char.charCodeAt(0) > 32 && char.charCodeAt(0) !== 127).join('');
  // The first colon ends the scheme (`blob:https://…` is a blob URL); anything before it that is
  // not a known scheme fails closed, including non-ASCII prefixes a URL parser would not strip.
  const scheme = /^([^:/?#]*):/.exec(normalized);
  if (!scheme) return true;
  const name = scheme[1].toLowerCase();
  if (ALLOWED_SCHEMES.has(name)) return true;
  if (!MEDIA_ATTRIBUTES.has(attributeName)) return false;
  return name === 'blob' || EMBEDDED_RASTER_IMAGE_RE.test(normalized);
}

/** The candidates of a `srcset` whose URL passes; the attribute goes when none does. */
function sanitizeSrcset(value) {
  const kept = [];
  let rest = String(value ?? '').trim();
  while (rest) {
    let url = /^\S+/.exec(rest)[0];
    rest = rest.slice(url.length);
    let descriptor = '';
    if (url.endsWith(',')) {
      url = url.replace(/,+$/, '');
    } else {
      const next = /^[^,]*/.exec(rest)[0];
      descriptor = next.trim();
      rest = rest.slice(next.length + 1);
    }
    rest = rest.trim();
    if (url && isAllowedUrl(url, 'srcset')) kept.push(descriptor ? `${url} ${descriptor}` : url);
  }
  return kept.join(', ');
}

/** DOM-based URL allow-list for document HTML. SSR fails closed to plain text. */
export function sanitizeHtml(html) {
  if (typeof document === 'undefined') return escapeHtml(html);
  const template = document.createElement('template');
  template.innerHTML = String(html ?? '');
  template.content.querySelectorAll(UNSAFE_ELEMENTS).forEach((element) => element.remove());
  template.content.querySelectorAll('*').forEach((element) => {
    for (const attribute of [...element.attributes]) {
      const name = attribute.name.toLowerCase();
      if (name.startsWith('on') || name === 'srcdoc' || name === 'formaction') {
        element.removeAttribute(attribute.name);
      } else if (name === 'srcset') {
        const candidates = sanitizeSrcset(attribute.value);
        if (candidates) element.setAttribute(attribute.name, candidates);
        else element.removeAttribute(attribute.name);
      } else if (URL_ATTRIBUTES.has(name) && !isAllowedUrl(attribute.value, name)) {
        element.removeAttribute(attribute.name);
      }
    }
  });
  return template.innerHTML;
}

/**
 * Parse an HTML string into flat block tokens using the browser's native parser.
 *
 * Each top-level element becomes an `element` token; significant top-level text
 * becomes a `text` token; recognized page-break comments become `break` tokens.
 * Returns [] when no DOM is available (SSR / tests inject `parseHtml` instead).
 */
function parseHtmlToTokens(html, breakComment) {
  if (typeof document === 'undefined') return [];

  const template = document.createElement('template');
  template.innerHTML = String(html ?? '');

  const tokens = [];

  template.content.childNodes.forEach((node) => {
    if (node.nodeType === COMMENT_NODE) {
      if (breakComment.test(node.textContent ?? '')) {
        tokens.push({ kind: 'break' });
      }
      return;
    }

    if (node.nodeType === TEXT_NODE) {
      const text = (node.textContent ?? '').trim();
      if (text) tokens.push({ kind: 'text', html: escapeHtml(text), text });
      return;
    }

    if (node.nodeType === ELEMENT_NODE) {
      const element = node;
      const breakBefore = element.hasAttribute('data-flow-break-before');
      const breakAfter = element.hasAttribute('data-flow-break-after');
      // The break markers are control hints, not output; strip them so they do
      // not leak into the rendered item html.
      element.removeAttribute('data-flow-break-before');
      element.removeAttribute('data-flow-break-after');

      tokens.push({
        kind: 'element',
        type: element.tagName.toLowerCase(),
        html: element.outerHTML,
        text: element.textContent ?? '',
        breakBefore,
        breakAfter,
      });
    }
  });

  return tokens;
}

function tokensToItems(tokens, options) {
  const idPrefix = options.idPrefix ?? '';
  const items = [];
  let breakBeforeNext = false;

  for (const token of tokens) {
    if (!token || token.kind === 'break') {
      breakBeforeNext = true;
      continue;
    }

    const type = token.type ?? 'text';
    const html = token.html ?? '';
    if (!html) continue;

    items.push({
      id: blockId(type, token.text ?? html, items.length, idPrefix),
      type,
      html,
      breakBefore: breakBeforeNext || Boolean(token.breakBefore),
    });

    // A break-after on this element is expressed as a break-before on the next
    // item, so the item shape stays parallel to markdownToFlowItems.
    breakBeforeNext = Boolean(token.breakAfter);
  }

  return items;
}

/**
 * Convert an HTML string into explicit Static.Flow items.
 *
 * Mirrors markdownToFlowItems: top-level blocks become items the flow algorithm
 * can move between pages. Splitting is block-level only — a single oversized
 * element (huge table, long list) is one item and will not split line-by-line.
 *
 * @param {string} html
 * @param {{ idPrefix?: string, breakComment?: RegExp, parseHtml?: (html: string) => Array }} [options]
 * @returns {Array<{ id: string, type: string, html: string, breakBefore: boolean }>}
 */
export function htmlToFlowItems(html = '', options = {}) {
  const breakComment = options.breakComment ?? PAGE_BREAK_COMMENT_RE;
  const parse = options.parseHtml ?? ((source) => parseHtmlToTokens(source, breakComment));
  const tokens = parse(html);
  return tokensToItems(Array.isArray(tokens) ? tokens : [], options);
}
