/**
 * What a brand kit declares for loading its fonts: stylesheet links (Google Fonts or a CSS
 * provider) and `@font-face` rules for self-hosted files. `BrandKitProvider` renders both.
 *
 * Only what the kit declares is loaded — `provider`/`source` (`google`, `css`), `cssUrl`, `files`
 * and `faces[].cssUrl` / `faces[].files` from the brandkit.json schema. A family with none is assumed to be
 * loaded by the template (an `@import` in its CSS) and is not guessed at. Relative URLs resolve
 * against the kit's `baseUrl`, else the directory of `sourceUrl` (where the kit was fetched from).
 *
 * Pure and DOM-free.
 */
import { isPlainObject, textOf } from '../utility/json.js';
import { brandKitRuntime } from './brand-kit-css-vars.js';
import { brandKitBaseUrl as baseUrlOf, resolveBrandKitUrl as resolveUrl } from './brand-kit-assets.js';

// Characters that could end the quoted CSS string (or the <style> element) a value is written into.
const UNSAFE_IN_CSS_STRING = /["\\\n\r\f<>]/;

const listFonts = (fonts) =>
  (Array.isArray(fonts) ? fonts : isPlainObject(fonts) ? Object.values(fonts) : []).filter(isPlainObject);

function providerOf(font) {
  if (font.provider === 'google' || font.provider === 'css') return font.provider;
  if (font.source === 'google' || font.source === 'css') return font.source;
  return textOf(font.cssUrl) ? 'css' : undefined;
}

/** `@font-face` takes one family name: the first of a stack, unquoted. */
const singleFamily = (family) => textOf(family.split(',')[0]?.replace(/^\s*(["'])(.*)\1\s*$/, '$2'));

function weightsOf(font) {
  const declared = Array.isArray(font.weights) ? font.weights : (font.faces ?? []).map((face) => face?.weight);
  const valid = declared.map(Number).filter((weight) => Number.isInteger(weight) && weight >= 1 && weight <= 1000);
  return [...new Set(valid)].sort((a, b) => a - b);
}

function googleFontsUrl(family, font) {
  const name = encodeURIComponent(family).replace(/%20/g, '+');
  const weights = weightsOf(font);
  const faces = Array.isArray(font.faces) ? font.faces : [];
  const styles = Array.isArray(font.styles) ? font.styles : faces.map((face) => face?.style);
  let axis = weights.length > 0 ? `:wght@${weights.join(';')}` : '';
  if (styles.includes('italic')) {
    const pairs = Array.isArray(font.styles)
      ? (styles.includes('normal') ? [0, 1] : [1]).flatMap((italic) =>
          (weights.length ? weights : [400]).map((weight) => [italic, weight]))
      : faces.filter((face) => face?.style === 'normal' || face?.style === 'italic')
          .map((face) => [face.style === 'italic' ? 1 : 0, Number(face.weight)])
          .filter(([, weight]) => Number.isInteger(weight) && weight >= 1 && weight <= 1000);
    const tuples = pairs.sort(([a, x], [b, y]) => a - b || x - y).map((pair) => pair.join(','));
    axis = `:ital,wght@${[...new Set(tuples)].join(';')}`;
  }
  return `https://fonts.googleapis.com/css2?family=${name}${axis}&display=swap`;
}

function fontFiles(font) {
  if (Array.isArray(font.files) && font.files.length > 0) {
    return font.files.filter(isPlainObject).map((file) => ({ ...file }));
  }
  if (!Array.isArray(font.faces)) return [];
  return font.faces.filter(isPlainObject).flatMap((face) => {
    if (Array.isArray(face.files)) {
      return face.files.filter(isPlainObject).map((file) => ({
        ...file,
        weight: file.weight ?? face.weight,
        style: file.style ?? face.style,
      }));
    }
    // `{ woff2: url, woff: url }`, the authoring shape.
    return Object.entries(isPlainObject(face.files) ? face.files : {}).map(([format, src]) => ({
      src,
      format,
      weight: face.weight,
      style: face.style,
    }));
  });
}

function cssFormat(file) {
  const hint = String(file.format ?? file.src ?? '').toLowerCase();
  if (hint.includes('woff2')) return 'woff2';
  if (hint.includes('woff')) return 'woff';
  if (hint.includes('otf') || hint.includes('opentype')) return 'opentype';
  return 'truetype';
}

function cssWeight(weight) {
  const value = String(weight ?? '').trim();
  return /^\d{1,4}(?:\s+\d{1,4})?$/.test(value) ? value : '400';
}

function fontFaceRule(family, file, base) {
  const src = resolveUrl(file.src, base);
  if (!src || UNSAFE_IN_CSS_STRING.test(src)) return undefined;
  return [
    '@font-face {',
    `  font-family: "${family}";`,
    `  src: url("${src}") format("${cssFormat(file)}");`,
    `  font-style: ${file.style === 'italic' ? 'italic' : 'normal'};`,
    `  font-weight: ${cssWeight(file.weight)};`,
    '  font-display: swap;',
    '}',
  ].join('\n');
}

/**
 * @param {object|null|undefined} brandKit
 * @param {{ sourceUrl?: string }} [options]
 * @returns {{ fontFaceCss: string, stylesheetUrls: string[] }}
 */
export function brandKitFontAssets(brandKit, options = {}) {
  if (!isPlainObject(brandKit)) return { fontFaceCss: '', stylesheetUrls: [] };
  const base = baseUrlOf(brandKit, options?.sourceUrl);
  const stylesheetUrls = [];
  const rules = [];
  const addStylesheet = (src) => {
    const url = resolveUrl(src, base);
    if (url && !/^data:/i.test(url) && !stylesheetUrls.includes(url)) stylesheetUrls.push(url);
  };

  // A kit published with `runtime` lists exactly what its four font roles need: stylesheet URLs,
  // and uploaded faces as data that goes through the same `@font-face` builder as everything else.
  const runtime = brandKitRuntime(brandKit);
  if (runtime) {
    for (const url of Array.isArray(runtime.fontStylesheets) ? runtime.fontStylesheets : []) addStylesheet(url);
    for (const face of Array.isArray(runtime.fontFaces) ? runtime.fontFaces : []) {
      if (!isPlainObject(face)) continue;
      const declared = textOf(face.family);
      const family = declared ? singleFamily(declared) : undefined;
      if (!family || UNSAFE_IN_CSS_STRING.test(family)) continue;
      const rule = fontFaceRule(family, face, base);
      if (rule && !rules.includes(rule)) rules.push(rule);
    }
    return { fontFaceCss: rules.join('\n'), stylesheetUrls };
  }

  for (const font of listFonts(brandKit.fonts)) {
    const declared = textOf(font.family);
    const family = declared ? singleFamily(declared) : undefined;
    if (!family || UNSAFE_IN_CSS_STRING.test(family)) continue;

    const provider = providerOf(font);
    if (provider) {
      const url = textOf(font.cssUrl)
        ? font.cssUrl
        : provider === 'google'
          ? googleFontsUrl(family, font)
          : undefined;
      addStylesheet(url);
    }

    for (const face of Array.isArray(font.faces) ? font.faces : []) addStylesheet(face?.cssUrl);
    if (provider) continue;

    for (const file of fontFiles(font)) {
      const rule = fontFaceRule(family, file, base);
      if (rule && !rules.includes(rule)) rules.push(rule);
    }
  }

  return { fontFaceCss: rules.join('\n'), stylesheetUrls };
}
