import * as React from 'react';
import { FlowText } from './flow-text';
import { FLOW_TEXT_INLINE_TAGS } from './flow-text-slice';

const TEXT_BLOCKS = new Set(['p', 'h1', 'h2', 'h3', 'h4', 'h5', 'h6']);
const ATTRIBUTE_NAMES: Record<string, string> = {
  class: 'className', tabindex: 'tabIndex', contenteditable: 'contentEditable', spellcheck: 'spellCheck',
  accesskey: 'accessKey', datetime: 'dateTime', itemprop: 'itemProp', itemscope: 'itemScope',
  itemtype: 'itemType', itemid: 'itemID', itemref: 'itemRef', autocapitalize: 'autoCapitalize',
  autocorrect: 'autoCorrect', inputmode: 'inputMode', enterkeyhint: 'enterKeyHint',
  contextmenu: 'contextMenu', 'xml:lang': 'xmlLang',
};

/** The parser has decoded entities. Keep authored attributes and CSS on the original element. */
function attributes(element: HTMLElement): Record<string, unknown> | null {
  const props: Record<string, unknown> = {};
  for (const attribute of Array.from(element.attributes)) {
    const name = attribute.name.toLowerCase();
    // React cannot reproduce string event handlers or !important declarations. Keep the original
    // HTML whole rather than silently changing it (also when a trusted/custom sanitizer is used).
    if (name.startsWith('on') || name === 'autofocus' ||
        (name === 'contenteditable' && attribute.value !== 'false') ||
        (name === 'hidden' && attribute.value === 'until-found')) return null;
    if (name === 'style') {
      const style: Record<string, string> = {};
      for (const property of Array.from(element.style)) {
        if (element.style.getPropertyPriority(property)) return null;
        const key = property.startsWith('--') ? property : property
          .replace(/^-ms-/, 'ms-').replace(/-([a-z])/g, (_, letter: string) => letter.toUpperCase());
        style[key] = element.style.getPropertyValue(property);
      }
      props.style = style;
    } else {
      props[ATTRIBUTE_NAMES[name] ?? name] = name === 'hidden' || name === 'itemscope' ? true : attribute.value;
    }
  }
  return props;
}

function inlineChildren(parent: HTMLElement): React.ReactNode[] | null {
  const children: React.ReactNode[] = [];
  for (const [index, node] of Array.from(parent.childNodes).entries()) {
    if (node.nodeType === 8) continue; // Comments have no text offset or visible content.
    if (node.nodeType === 3) { children.push(node.textContent ?? ''); continue; }
    if (node.nodeType !== 1) return null;
    const element = node as HTMLElement;
    const tag = element.tagName.toLowerCase();
    if (!FLOW_TEXT_INLINE_TAGS.has(tag)) return null;
    const props = attributes(element);
    const nested = inlineChildren(element);
    if (!props || !nested) return null;
    children.push(React.createElement(tag, { ...props, key: index }, ...nested));
  }
  return children;
}

/** Internal default renderer: only native inline-text p/headings opt into line splitting. */
export function htmlToFlowText(html: string): React.ReactElement | null {
  if (typeof document === 'undefined') return null;
  const template = document.createElement('template');
  template.innerHTML = html;
  const nodes = Array.from(template.content.childNodes).filter((node) =>
    node.nodeType !== 8 && !(node.nodeType === 3 && !(node.textContent ?? '').trim()));
  if (nodes.length !== 1 || nodes[0].nodeType !== 1) return null;
  const element = nodes[0] as HTMLElement;
  const tag = element.tagName.toLowerCase();
  if (!TEXT_BLOCKS.has(tag)) return null;
  const props = attributes(element);
  const children = inlineChildren(element);
  if (!props || !children) return null;
  return React.createElement(FlowText, { ...props, as: tag as keyof HTMLElementTagNameMap }, ...children);
}
